package com.aistock.prediction.question;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import com.fasterxml.jackson.databind.node.*;
class QuestionFactsTest {
 @Test void frozenSourceWhitelistAndQuestionHash(){var s=QuestionSamples.analysis(false);String before=s.toString();((ObjectNode)s.path("context").path("facts")).put("EMAIL","private").put("QA_MA_DEF","evil");before=s.toString();var a=QuestionFacts.build(s,"均线？","test",QuestionSamples.M);assertEquals(before,s.toString());assertFalse(a.values().containsKey("EMAIL"));assertFalse(a.values().containsKey("PRED_VERIFICATION"));assertNotEquals("evil",a.values().get("QA_MA_DEF"));assertNotEquals(a.hash(),QuestionFacts.build(s,"风险？","test",QuestionSamples.M).hash());assertNotEquals(a.hash(),QuestionFacts.build(s,"均线？","other",QuestionSamples.M).hash());s.put("analysisId","44444444-4444-4444-8444-444444444444");assertNotEquals(a.hash(),QuestionFacts.build(s,"均线？","test",QuestionSamples.M).hash());}
 @Test void predictionEvidenceRemainsSaved(){var s=QuestionSamples.analysis(true);var f=QuestionFacts.build(s,"验证？","test",QuestionSamples.M);assertEquals("尚无有效样本，不能评价准确性",f.values().get("PRED_VERIFICATION"));assertTrue(f.context().path("sourceContext").path("prediction").path("verificationVersionId").isNull());((ObjectNode)s.path("context")).put("priceBasis","FAKE");assertThrows(com.aistock.common.BusinessException.class,()->QuestionFacts.build(s,"验证？","test",QuestionSamples.M));}
}
